from edit import *
q=load(32);s=q['caseStudy']['summary'];rep(s,'en','The case follows alteplase eligibility screening, thrombectomy preparation, and post-reperfusion deterioration.','The stroke team is evaluating the acute neurologic change and treatment options.');rep(s,'zh','本病例追踪 alteplase 适用性筛查、血栓取出术准备，以及再灌注后病情恶化。','卒中团队正在评估急性神经变化及治疗选择。');c=content(q,0);old=pair('The neurologist states the client is not a candidate for IV alteplase because of the INR and orders CTA head and neck to evaluate for large-vessel occlusion and potential mechanical thrombectomy. ','神经科医生说明患者因 INR 不符合 IV alteplase 条件，并医嘱行头颈 CTA，以评估是否有大血管闭塞及机械取栓可能性。')
